// Brute-force ground-truth verifier: NonZero winding area by unit-cell counting.
fn wind(rings:&[Vec<(i64,i64)>], px:f64, py:f64)->i32{
    let mut w=0i32;
    for r in rings{ let n=r.len();
        for i in 0..n{ let (x0,y0)=r[i]; let (x1,y1)=r[(i+1)%n];
            let (x0,y0,x1,y1)=(x0 as f64,y0 as f64,x1 as f64,y1 as f64);
            if y0<=py { if y1>py { // upward crossing
                let cr=(x1-x0)*(py-y0)-(px-x0)*(y1-y0);
                if cr>0.0 {w+=1;} } }
            else if y1<=py { let cr=(x1-x0)*(py-y0)-(px-x0)*(y1-y0);
                if cr<0.0 {w-=1;} }
        }
    }
    w
}
fn area(r:&[(i64,i64)])->f64{ if r.len()<3 {return 0.0;} let n=r.len(); let mut a=0.0f64;
    // Clipper2 order: closing edge first
    a += ((r[n-1].1 + r[0].1) as f64) * ((r[n-1].0 - r[0].0) as f64);
    for i in 0..n-1 { a += ((r[i].1 + r[i+1].1) as f64) * ((r[i].0 - r[i+1].0) as f64); }
    0.5*a }
fn main(){
    let r1=vec![(0,0),(50,0),(50,50),(0,50)];
    let r2=vec![(25,25),(75,25),(75,75),(25,75)];
    let r3=vec![(50,50),(100,50),(100,100),(50,100)];
    let rings=vec![r1.clone(),r2.clone(),r3.clone()];
    let mut cells=0i64;
    for x in -5..105 { for y in -5..105 {
        let w=wind(&rings, x as f64+0.5, y as f64+0.5);
        if w!=0 {cells+=1;}
    }}
    println!("NonZero unit-cell area = {}", cells);
    // quadrant windings around (50,50)
    for (dx,dy,name) in [(-0.5,-0.5,"SW"),(0.5,-0.5,"SE"),(0.5,0.5,"NE"),(-0.5,0.5,"NW")]{
        println!("  {} w={}", name, wind(&rings,50.0+dx,50.0+dy));
    }
    // truth ring area, Clipper2 accumulation order
    let truth=vec![(0,0),(50,0),(50,25),(75,25),(75,50),(100,50),(100,100),(50,100),(50,75),(25,75),(25,50),(0,50)];
    println!("truth ring shoelace = {}", area(&truth));
    println!("printf %g -> {}", format_g(area(&truth)));
    println!("r1 area={} r2={} r3={}", area(&r1),area(&r2),area(&r3));
    // hole check: is complement connected? flood fill outside on 110x110 grid of non-covered cells
    let n=112usize; let idx=|x:usize,y:usize| y*n+x;
    let mut inside=vec![false;n*n];
    for x in 0..n { for y in 0..n {
        let px=(x as f64)-6.0+0.5; let py=(y as f64)-6.0+0.5;
        inside[idx(x,y)] = wind(&rings,px,py)!=0; }}
    let mut seen=vec![false;n*n]; let mut st=vec![(0usize,0usize)]; seen[0]=true; let mut cnt=0;
    while let Some((x,y))=st.pop(){ cnt+=1;
        let nb=[(x.wrapping_sub(1),y),(x+1,y),(x,y.wrapping_sub(1)),(x,y+1)];
        for (a,b) in nb { if a<n&&b<n&&!seen[idx(a,b)]&&!inside[idx(a,b)]{seen[idx(a,b)]=true;st.push((a,b));} } }
    let empty=inside.iter().filter(|v|!**v).count();
    println!("outside-reachable empty cells={} total empty={} => holes {}", cnt, empty, if cnt==empty {"NONE"} else {"PRESENT"});
}
fn format_g(v:f64)->String{ format!("{}", v) }
